package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReferenceType#getGenericSignature
 */
public class ReferenceType_getGenericSignature_TriageGen2Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Given
        // We need to mock JavaType because _referencedType is a field in ReferenceType
        // Since ReferenceType is abstract/protected, we use the construct method or Mockito to create a subclass/mock
        JavaType mockReferencedType = Mockito.mock(JavaType.class);

        // We mock the behavior of _referencedType.getGenericSignature(sb)
        // The method under test calls: sb = _referencedType.getGenericSignature(sb);
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("MockedType");
            return sb;
        });

        // Use construct to create the ReferenceType instance
        // We need to inject the mockReferencedType. 
        // Since we cannot access protected field directly easily without reflection if it's private,
        // but based on the provided code, _referencedType is used.
        // In Jackson, ReferenceType is typically constructed via construct()
        ReferenceType referenceType = Mockito.mock(ReferenceType.class, Mockito.CALLS_REAL_METHODS);

        // Injecting the mock via reflection because _referencedType is a private/protected field
        try {
            java.lang.reflect.Field field = ReferenceType.class.getDeclaredField("_referencedType");
            field.setAccessible(true);
            field.set(referenceType, mockReferencedType);
        } catch (Exception e) {
            Assert.fail("Failed to inject mockReferencedType: " + e.getMessage());
        }

        StringBuilder sb = new StringBuilder("Start");

        // When
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Then
        // Expected logic: 
        // 1. sb.append('<') -> "Start<"
        // 2. _referencedType.getGenericSignature(sb) -> "Start<MockedType"
        // 3. sb.append(">;") -> "Start<MockedType>;"
        String expected = "Start<MockedType>;";
        Assert.assertEquals(expected, result.toString());
        Assert.assertEquals(expected, sb.toString());
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Given
        JavaType mockReferencedType = Mockito.mock(JavaType.class);
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder sb = invocation.getArgument(0);
            sb.append("Inner");
            return sb;
        });

        ReferenceType referenceType = Mockito.mock(ReferenceType.class, Mockito.CALLS_REAL_METHODS);
        try {
            java.lang.reflect.Field field = ReferenceType.class.getDeclaredField("_referencedType");
            field.setAccessible(true);
            field.set(referenceType, mockReferencedType);
        } catch (Exception e) {
            Assert.fail(e.getMessage());
        }

        StringBuilder sb = new StringBuilder();

        // When
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Then
        Assert.assertEquals("<Inner>;", result.toString());
    }

    @Test(expected = RuntimeException.class)
    public void testGetGenericSignature_ExceptionInReferencedType() {
        // Given
        JavaType mockReferencedType = Mockito.mock(JavaType.class);
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenThrow(new RuntimeException("Nested Error"));

        ReferenceType referenceType = Mockito.mock(ReferenceType.class, Mockito.CALLS_REAL_METHODS);
        try {
            java.lang.reflect.Field field = ReferenceType.class.getDeclaredField("_referencedType");
            field.setAccessible(true);
            field.set(referenceType, mockReferencedType);
        } catch (Exception e) {
            Assert.fail(e.getMessage());
        }

        StringBuilder sb = new StringBuilder();

        // When
        referenceType.getGenericSignature(sb);

        // Then - Exception expected
    }
}
